from copy import deepcopy


class QuotaLedger:
    def __init__(self, soft_limit, hard_limit):
        for value in (soft_limit, hard_limit):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("limits must be integers")
        if soft_limit < 0 or soft_limit >= hard_limit:
            raise ValueError("limits must satisfy 0 <= soft < hard")
        self.soft_limit = soft_limit
        self.hard_limit = hard_limit
        self._clients = {}

    def observe(self, client, window, query):
        if not isinstance(client, str):
            raise TypeError("client must be a string")
        if not client.strip():
            raise ValueError("client cannot be empty")
        if not isinstance(query, str):
            raise TypeError("query must be a string")

        record = self._clients.get(client)
        if record is None or record["window"] != window:
            record = {"window": deepcopy(window), "count": 0, "queries": []}
            self._clients[client] = record
        record["count"] += 1
        cleaned = query.strip()
        if cleaned:
            record["queries"].append(cleaned)
        else:
            return "invalid"
        if record["count"] > self.hard_limit:
            return "forbidden"
        if record["count"] > self.soft_limit:
            return "throttled"
        return "accepted"

    def clear(self):
        self._clients.clear()

    def snapshot(self):
        return dict(self._clients)

